package com.bank.linkedlist;

import org.junit.jupiter.api.Test;
import java.util.*;
import static org.assertj.core.api.Assertions.*;

class LinkedListInternalsTest {

    // ═══ Doubly-linked: addFirst/addLast O(1) ═══
    @Test
    void addFirstAndLast_O1() {
        LinkedList<String> list = new LinkedList<>();
        list.addFirst("B");    // [B]
        list.addFirst("A");    // [A, B]  — A becomes new head
        list.addLast("C");     // [A, B, C]  — C becomes new tail
        assertThat(list).containsExactly("A", "B", "C");
    }

    // ═══ get(index): O(n) traversal ═══
    @Test
    void get_traversesFromCloserEnd() {
        LinkedList<String> list = new LinkedList<>();
        for (int i = 0; i < 1000; i++) list.add("TXN-" + i);

        // get(0): traverse from head → 0 hops
        assertThat(list.get(0)).isEqualTo("TXN-0");
        // get(999): traverse from tail → 0 hops (optimization!)
        assertThat(list.get(999)).isEqualTo("TXN-999");
        // get(500): traverse from head → 500 hops (worst case)
        assertThat(list.get(500)).isEqualTo("TXN-500");
    }

    // ═══ Deque operations ═══
    @Test
    void deque_fifoAndLifo() {
        LinkedList<String> deque = new LinkedList<>();
        // FIFO (queue): addLast + removeFirst
        deque.addLast("TXN-001");
        deque.addLast("TXN-002");
        assertThat(deque.removeFirst()).isEqualTo("TXN-001");  // FIFO!

        // LIFO (stack): addFirst + removeFirst
        deque.addFirst("TXN-003");
        assertThat(deque.removeFirst()).isEqualTo("TXN-003");  // LIFO!
    }

    // ═══ ListIterator: O(1) insert at position ═══
    @Test
    void listIterator_O1InsertAtPosition() {
        LinkedList<String> list = new LinkedList<>(List.of("A", "C", "E"));
        ListIterator<String> it = list.listIterator(1);  // before "C"
        it.add("B");  // insert B before C — O(1)! Just pointer update!
        it.next();     // advance past C
        it.add("D");  // insert D after C — O(1)!
        assertThat(list).containsExactly("A", "B", "C", "D", "E");
    }

    // ═══ removeFirst/removeLast: O(1) ═══
    @Test
    void removeEnds_O1() {
        LinkedList<String> list = new LinkedList<>(List.of("A", "B", "C"));
        assertThat(list.removeFirst()).isEqualTo("A");  // O(1)
        assertThat(list.removeLast()).isEqualTo("C");   // O(1)
        assertThat(list).containsExactly("B");
    }

    // ═══ Memory: ~24 bytes per node ═══
    @Test
    void memoryOverhead() {
        // Each Node: object header (~16 bytes) + item ref (8) + next ref (8) + prev ref (8) = ~40 bytes
        // vs ArrayList: ~4-8 bytes per element (just the reference in the array)
        // LinkedList uses 5-10x MORE memory than ArrayList!
        // For 1M elements: ArrayList ~8MB, LinkedList ~40MB
        assertThat(true).isTrue();
    }
}
